ALTER POLICY "history_read" ON "work_history" TO sep_runtime USING ("work_history"."organization_id" = nullif(current_setting('sep.organization_id', true), '')::uuid AND "work_history"."event_id" = nullif(current_setting('sep.event_id',true),'')::uuid AND EXISTS (SELECT 1 FROM author_works w WHERE w.id="work_history"."work_id" AND w.organization_id="work_history"."organization_id" AND w.event_id="work_history"."event_id") AND (EXISTS (SELECT 1 FROM author_works w WHERE w.id="work_history"."work_id" AND w.owner_id=nullif(current_setting('sep.person_id',true),'')::uuid) OR "work_history"."actor"='staff' OR "work_history"."action" IN ('submitted','final_submitted','withdrawn')));